import math
class WelfordAnomalyDetector:
    def __init__(self):
        self.count = 0
        self.mean = 0.0
        self.M2 = 0.0
    def update(self, x):
        self.count += 1
        delta = x - self.mean
        self.mean += delta / self.count
        self.M2 += delta * (x - self.mean)
    @property
    def variance(self):
        return self.M2 / (self.count - 1) if self.count > 1 else 0.0
